<script setup lang="ts">
import { computed, ref } from 'vue'
import { ElAlert, ElButton, ElTag } from 'element-plus'
import 'element-plus/dist/index.css'
import { demoLocations, entries, knowledgeTerms, themeRoutes, type Entry, type EntryStatus } from '../data/demo'

type Tab='overview'|'entries'|'draft'|'assets'|'content'|'locations'
const tab=ref<Tab>('overview'); const rows=ref<Entry[]>(entries.map(i=>({...i}))); const search=ref(''); const notice=ref('')
const draftScene=ref('小西天殿内群像'); const draftType=ref('悬塑'); const draftResult=ref<Entry|null>(null)
const nav=[['overview','采编概览','▦'],['entries','对照条目','鉴'],['draft','AI 起草','AI'],['assets','素材与版权','图'],['content','字典 / 路线','册'],['locations','取景地管理','⌖']] as const
const filtered=computed(()=>rows.value.filter(i=>!search.value||i.title.includes(search.value)||i.targetName.includes(search.value)))
const statusOrder:EntryStatus[]=['草稿','待核查','已核查','已发布']
function nextStatus(item:Entry){const i=statusOrder.indexOf(item.status);if(item.status==='待核查'&&item.sources.length<2){notice.value='信源不足：至少 2 条，且包含 1 条 S/A 级';return}if(i<statusOrder.length-1){item.status=statusOrder[i+1];notice.value=`${item.title} 已进入「${item.status}」`}}
function returnDraft(item:Entry){item.status='草稿';notice.value='条目已退回草稿'}
function generateDraft(){draftResult.value={...entries[0],id:Date.now(),title:`${draftScene.value} × ${draftType.value}研究条目`,gameScene:draftScene.value,targetName:`待确认的${draftType.value}实例`,targetType:draftType.value,status:'草稿',sources:[],credibility:0,saved:false}}
function saveDraft(){if(!draftResult.value)return;rows.value.unshift(draftResult.value);draftResult.value=null;notice.value='AI 初稿已保存为草稿，等待补充信源与人工核查';tab.value='entries'}
</script>

<template>
  <div class="editorial-shell">
    <aside><router-link to="/" class="brand"><span>识</span><div><strong>悟空识古</strong><small>采编工作台</small></div></router-link><nav><button v-for="item in nav" :key="item[0]" :class="{active:tab===item[0]}" @click="tab=item[0]"><i>{{ item[2] }}</i>{{ item[1] }}<b v-if="item[0]==='entries'">{{ rows.length }}</b></button></nav><footer><div><span>编</span><p><strong>内容编辑</strong><small>editor · 演示账号</small></p></div><router-link to="/">查看门户 ↗</router-link></footer></aside>
    <section class="workspace"><header><div><strong>{{ nav.find(i=>i[0]===tab)?.[1] }}</strong><small>样板地：隰县小西天</small></div><div><span class="env">AI_PROVIDER=mock</span><span class="avatar">编</span></div></header><main><div class="page-title"><div><h1>{{ nav.find(i=>i[0]===tab)?.[1] }}</h1><p>{{ tab==='overview'?'从 AI 初稿到人工核查、发布的完整内容流水线':'演示数据保存在当前页面会话中' }}</p></div><button v-if="tab==='entries'" class="primary">+ 新建条目</button></div><div v-if="notice" class="notice">{{ notice }}<button @click="notice=''">×</button></div>

      <template v-if="tab==='overview'">
        <div class="stats"><article><span>样板条目</span><strong>{{ rows.length }}</strong><small>目标 10-15 条</small></article><article><span>已发布</span><strong>{{ rows.filter(i=>i.status==='已发布').length }}</strong><small>均含演示信源</small></article><article><span>待核查</span><strong>{{ rows.filter(i=>i.status==='待核查').length }}</strong><small>需要人工处理</small></article><article class="warn"><span>占位素材</span><strong>{{ rows.length*2 }}</strong><small>对外演示前必须清零</small></article></div>
        <div class="overview-grid"><section class="panel workflow"><div class="panel-head"><h2>内容生产工作流</h2><button @click="tab='entries'">进入条目管理</button></div><div class="flow"><div v-for="status in statusOrder" :key="status"><b>{{ rows.filter(i=>i.status===status).length }}</b><span>{{ status }}</span><i v-if="status!=='已发布'">→</i></div></div><p>只有信源满足规则且状态为“已核查”的条目可以发布。</p></section><section class="panel"><div class="panel-head"><h2>待办核查</h2></div><div v-for="item in rows.filter(i=>i.status==='待核查'||i.status==='已核查').slice(0,4)" :key="item.id" class="todo"><span :class="item.status">{{ item.status }}</span><div><strong>{{ item.title }}</strong><small>{{ item.sources.length }} 个信源 · {{ item.targetType }}</small></div><button @click="tab='entries'">处理</button></div></section><section class="panel compliance"><div class="panel-head"><h2>版权合规检查</h2><span>内部开发</span></div><div class="license"><b>24</b><span>placeholder</span><i></i></div><div class="license ok"><b>0</b><span>official / CC</span><i></i></div><p>当前素材仅用于内部页面开发，不满足对外演示条件。</p><button @click="tab='assets'">打开素材看板</button></section><section class="panel"><div class="panel-head"><h2>样板地进度</h2><span>小西天</span></div><div class="progress"><strong>53%</strong><i><em style="width:53%"></em></i><span>8 / 15 条已发布</span></div><dl><div><dt>字典术语</dt><dd>{{ knowledgeTerms.length }}</dd></div><div><dt>主题路线</dt><dd>{{ themeRoutes.length }}</dd></div><div><dt>取景地数据</dt><dd>{{ demoLocations.length }}</dd></div></dl></section></div>
      </template>

      <template v-else-if="tab==='entries'">
        <section class="panel table-panel"><div class="tools"><input v-model="search" placeholder="搜索条目或现实文物"><select><option>全部状态</option><option v-for="s in statusOrder" :key="s">{{ s }}</option></select><select><option>全部类型</option><option>悬塑</option><option>彩塑</option><option>木构</option></select></div><table><thead><tr><th>条目</th><th>现实文物</th><th>信源</th><th>素材</th><th>状态</th><th>流转操作</th></tr></thead><tbody><tr v-for="item in filtered" :key="item.id"><td><strong>{{ item.gameScene }}</strong><small>{{ item.gameCategory }} · {{ item.dynasty }}代</small></td><td>{{ item.targetName }}<small>{{ item.targetType }}</small></td><td><b :class="item.sources.length>=2?'good':'bad'">{{ item.sources.length }}</b> 条</td><td><span class="placeholder">placeholder × 2</span></td><td><span :class="['status',item.status]">{{ item.status }}</span></td><td><button v-if="item.status!=='已发布'" class="link" @click="nextStatus(item)">{{ item.status==='已核查'?'发布':'推进' }}</button><button v-if="item.status!=='草稿'" class="link muted" @click="returnDraft(item)">退回</button><button class="link">编辑</button></td></tr></tbody></table></section>
      </template>

      <template v-else-if="tab==='draft'">
        <div class="draft-layout"><section class="panel draft-form"><div class="panel-head"><h2>AI 起草工作台</h2><span>Mock · 演示版</span></div><p>选择场景和文物类型，生成符合条目模板的结构化初稿。不会调用真实模型。</p><label>游戏场景<input v-model="draftScene"></label><label>现实文物类型<select v-model="draftType"><option>悬塑</option><option>彩塑</option><option>木构</option><option>壁画</option><option>构件</option></select></label><button class="primary" @click="generateDraft">生成结构化初稿</button></section><section class="panel draft-preview"><div class="panel-head"><h2>初稿预览</h2><span v-if="draftResult">未保存</span></div><div v-if="!draftResult" class="blank">等待生成初稿</div><template v-else><label>条目标题<input v-model="draftResult.title"></label><label>对照说明<textarea v-model="draftResult.summary"></textarea></label><div class="source-warning">信源占位：请添加至少 2 条信源，其中至少 1 条为 S/A 级，再提交核查。</div><footer><button @click="draftResult=null">放弃</button><button class="primary" @click="saveDraft">保存为草稿</button></footer></template></section></div>
      </template>

      <template v-else-if="tab==='assets'">
        <div class="asset-stats"><article class="red"><strong>24</strong><span>待替换占位素材</span></article><article><strong>0</strong><span>官方授权</span></article><article><strong>0</strong><span>CC BY / CC0</span></article><article><strong>0%</strong><span>合规素材占比</span></article></div><el-alert title="对外演示前必须将 placeholder 素材清零，并补全 License、署名和来源 URL。" type="warning" :closable="false" show-icon/><section class="panel table-panel asset-table"><div class="panel-head"><h2>素材登记</h2><el-button type="primary" size="small">登记素材</el-button></div><table><thead><tr><th>素材</th><th>类型</th><th>关联条目</th><th>License</th><th>署名 / 来源</th><th>状态</th></tr></thead><tbody><tr v-for="item in rows.slice(0,6)" :key="item.id"><td><strong>{{ item.gameScene }} 对照图</strong></td><td>游戏截图 + 现实照片</td><td>{{ item.title }}</td><td><el-tag type="danger" size="small">placeholder</el-tag></td><td class="bad">未填写</td><td><el-tag type="warning" size="small">待替换</el-tag></td></tr></tbody></table></section>
      </template>

      <template v-else-if="tab==='content'">
        <div class="content-grid"><section class="panel"><div class="panel-head"><h2>知识字典</h2><button>+ 新建术语</button></div><div v-for="item in knowledgeTerms" :key="item.term" class="content-row"><div><strong>{{ item.term }}</strong><small>{{ item.category }} · {{ item.related.join(' / ') }}</small></div><span>已发布</span><button>编辑</button></div></section><section class="panel"><div class="panel-head"><h2>主题路线</h2><button>+ 新建路线</button></div><div v-for="item in themeRoutes" :key="item.id" class="content-row"><div><strong>{{ item.name }}</strong><small>{{ item.days }} 天 · {{ item.locationIds.length }} 个地点</small></div><span>已发布</span><button>编辑</button></div></section></div>
      </template>

      <template v-else-if="tab==='locations'">
        <section class="panel table-panel"><div class="panel-head"><h2>山西取景地</h2><span>已由 16 处扩充至 {{ demoLocations.length }} 处</span></div><table><thead><tr><th>ID</th><th>名称</th><th>城市</th><th>区县</th><th>分类</th><th>坐标</th><th>操作</th></tr></thead><tbody><tr v-for="item in demoLocations" :key="item.id"><td>{{ item.id }}</td><td><strong>{{ item.name }}</strong></td><td>{{ item.city }}</td><td>{{ item.district }}</td><td>{{ item.tags[0] }}</td><td>{{ item.lng.toFixed(3) }}, {{ item.lat.toFixed(3) }}</td><td><button class="link">地图校验</button><button class="link">编辑</button></td></tr></tbody></table></section>
      </template>
    </main></section>
  </div>
</template>

<style scoped>
